    "content": "interface:\n  display_name: \"Edit a TimDS Design System\"\n  short_description: \"Edit, manage media, validate, and submit TimDS changes\"\n  default_prompt: \"Use $timds-edit-design-system to update this client design system and submit the change for review.\"\n"
