    "content": "{\n  \"schemaVersion\": 2,\n  \"systemId\": \"example/core\",\n  \"name\": \"Example core\",\n  \"description\": \"Repository-owned visual and interface standards.\",\n  \"version\": \"2026.10.13-1\",\n  \"artifact\": {\n    \"entry\": \"index.html\",\n    \"publishRef\": \"timds-published\"\n  },\n  \"media\": {\n    \"portalUrl\": \"https://host.example.com\"\n  },\n  \"workspace\": {\n    \"dev\": [\n      \"node\",\n      \"scripts/dev.mjs\"\n    ],\n    \"build\": [\n      \"node\",\n      \"scripts/build.mjs\"\n    ],\n    \"check\": [\n      \"node\",\n      \"scripts/check.mjs\"\n    ]\n  },\n  \"bundle\": {\n    \"include\": [\n      \"dist/tokens.css\",\n      \"dist/styles/system.css\"\n    ]\n  },\n  \"provider\": {\n    \"kind\": \"hosted\",\n    \"url\": \"https://host.example.com\",\n    \"apiVersion\": 1\n  }\n}\n"
