    "content": "// The toolkit builds dist. Vite copies public assets without transforming HTML.\nimport {existsSync} from 'node:fs';\nimport {fileURLToPath} from 'node:url';\nimport {defineConfig} from 'vite';\nimport {cloudflare} from '@cloudflare/vite-plugin';\nconst root=fileURLToPath(new URL('.',import.meta.url));\nif(existsSync(new URL('./index.html',import.meta.url)))throw new Error('TimDS static Preview cannot accept a root index.html; review source conversion');\nif(!existsSync(new URL('./dist/index.html',import.meta.url)))throw new Error('Run npm run build:preview before cf build or deploy');\nexport default defineConfig({root,publicDir:fileURLToPath(new URL('./dist',import.meta.url)),plugins:[cloudflare()]});\n"
